def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Long 2-lines may be interrupted by a 3x3 marker.
    vertical = [c for c in range(w)
                if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]
    horizontal = [r for r in range(h)
                  if sum(grid[r][c] == 2 for c in range(w)) >= w - 3]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    def ray_row(r):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = 1

    def ray_col(c):
        for r in range(h):
            if grid[r][c] == 0:
                out[r][c] = 1

    def patch(r, c):
        for rr in range(r - 1, r + 2):
            for cc in range(c - 1, c + 2):
                if 0 <= rr < h and 0 <= cc < w:
                    # Preserve the crossing center and all marker cells.
                    if (rr, cc) != (r, c) and grid[rr][cc] != 3:
                        out[rr][cc] = 1

    for r, c in centers:
        if c in vertical:
            ray_row(r)
            for vc in vertical:
                if vc != c:
                    patch(r, vc)

        if r in horizontal:
            ray_col(c)
            for hr in horizontal:
                if hr != r:
                    patch(hr, c)

    return out
